import csv
import datetime as dt
import io
import json
import sqlite3
from dataclasses import dataclass
from functools import wraps
from pathlib import Path
from flask import Flask, g, jsonify, request, send_file, abort

DB_PATH = Path('/workspace/sprat.sqlite3')

ROLE_LEVEL = {'guest': 0, 'analyst': 1, 'manager': 2, 'admin': 3}


def now_iso():
    return dt.datetime.utcnow().replace(microsecond=0).isoformat() + 'Z'


def connect_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn


def get_db():
    if 'db' not in g:
        g.db = connect_db()
    return g.db


def init_db():
    conn = connect_db()
    cur = conn.cursor()
    cur.executescript(
        '''
        PRAGMA foreign_keys = ON;
        CREATE TABLE IF NOT EXISTS projects (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            sensitivity TEXT NOT NULL DEFAULT 'low',
            owner TEXT NOT NULL DEFAULT 'admin'
        );
        CREATE TABLE IF NOT EXISTS analyses (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            project_id INTEGER NOT NULL,
            name TEXT NOT NULL,
            description TEXT NOT NULL DEFAULT '',
            status TEXT NOT NULL DEFAULT 'draft',
            FOREIGN KEY(project_id) REFERENCES projects(id)
        );
        CREATE TABLE IF NOT EXISTS items (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            analysis_id INTEGER NOT NULL,
            kind TEXT NOT NULL,
            title TEXT NOT NULL,
            description TEXT NOT NULL DEFAULT '',
            actor TEXT,
            trigger TEXT,
            outcome TEXT,
            classifications TEXT NOT NULL DEFAULT '[]',
            source_policy_ref TEXT,
            source_policy_excerpt TEXT,
            rationale TEXT,
            sensitive_notes TEXT,
            legal_compliance TEXT,
            active INTEGER NOT NULL DEFAULT 1,
            created_by TEXT NOT NULL,
            created_at TEXT NOT NULL,
            updated_by TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            version INTEGER NOT NULL DEFAULT 1,
            FOREIGN KEY(analysis_id) REFERENCES analyses(id)
        );
        CREATE TABLE IF NOT EXISTS links (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            source_item_id INTEGER NOT NULL,
            target_item_id INTEGER NOT NULL,
            relation TEXT NOT NULL,
            primary_link INTEGER NOT NULL DEFAULT 0,
            created_by TEXT NOT NULL,
            created_at TEXT NOT NULL,
            note TEXT NOT NULL DEFAULT '',
            FOREIGN KEY(source_item_id) REFERENCES items(id),
            FOREIGN KEY(target_item_id) REFERENCES items(id)
        );
        CREATE TABLE IF NOT EXISTS audits (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            entity_type TEXT NOT NULL,
            entity_id INTEGER NOT NULL,
            action TEXT NOT NULL,
            previous_state TEXT,
            new_state TEXT,
            changed_by TEXT NOT NULL,
            changed_at TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS approvals (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            entity_type TEXT NOT NULL,
            entity_id INTEGER NOT NULL,
            requested_by TEXT NOT NULL,
            approved_by TEXT,
            status TEXT NOT NULL,
            reason TEXT NOT NULL,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL
        );
        '''
    )
    if cur.execute('SELECT COUNT(*) AS c FROM projects').fetchone()['c'] == 0:
        cur.execute("INSERT INTO projects(name, sensitivity, owner) VALUES (?, ?, ?)", ('Demo project', 'low', 'admin'))
        cur.execute("INSERT INTO analyses(project_id, name, description, status) VALUES (?, ?, ?, ?)", (1, 'Baseline analysis', 'Initial example analysis', 'approved'))
    conn.commit()
    conn.close()


def actor_from_request():
    role = request.headers.get('X-Role', 'guest').lower()
    user = request.headers.get('X-User', role)
    project = request.headers.get('X-Project', '1')
    scope = request.headers.get('X-Scope', '1')
    return {'role': role, 'user': user, 'project': project, 'scope': scope}


def require_role(min_role):
    def deco(fn):
        @wraps(fn)
        def wrapper(*args, **kwargs):
            actor = actor_from_request()
            if ROLE_LEVEL.get(actor['role'], 0) < ROLE_LEVEL[min_role]:
                return jsonify({'error': 'forbidden'}), 403
            g.actor = actor
            return fn(*args, **kwargs)
        return wrapper
    return deco


def serialize_item(row):
    d = dict(row)
    d['classifications'] = json.loads(d['classifications']) if d.get('classifications') else []
    return d


def audit(entity_type, entity_id, action, prev, new):
    db = get_db()
    actor = getattr(g, 'actor', actor_from_request())
    db.execute(
        'INSERT INTO audits(entity_type, entity_id, action, previous_state, new_state, changed_by, changed_at) VALUES (?, ?, ?, ?, ?, ?, ?)',
        (entity_type, entity_id, action, json.dumps(prev), json.dumps(new), actor['user'], now_iso())
    )
    db.commit()


def project_visible(project_id):
    db = get_db()
    row = db.execute('SELECT * FROM projects WHERE id=?', (project_id,)).fetchone()
    return row


def sensitivity_block(actor, project):
    if project['sensitivity'] == 'sensitive' and actor['role'] == 'guest':
        return True
    return False


def app_error(msg, code=400):
    return jsonify({'error': msg}), code


def create_app():
    app = Flask(__name__)
    init_db()

    @app.teardown_appcontext
    def close_db(exc):
        db = g.pop('db', None)
        if db is not None:
            db.close()

    @app.get('/')
    def index():
        return jsonify({'service': 'SPRAT', 'status': 'ok'})

    @app.get('/projects')
    def projects():
        rows = get_db().execute('SELECT * FROM projects').fetchall()
        return jsonify([dict(r) for r in rows])

    @app.post('/projects')
    @require_role('admin')
    def create_project():
        data = request.get_json(force=True)
        db = get_db()
        cur = db.execute('INSERT INTO projects(name, sensitivity, owner) VALUES (?, ?, ?)', (data['name'], data.get('sensitivity', 'low'), data.get('owner', g.actor['user'])))
        db.commit()
        return jsonify({'id': cur.lastrowid}), 201

    @app.get('/analyses/<int:analysis_id>')
    def get_analysis(analysis_id):
        row = get_db().execute('SELECT * FROM analyses WHERE id=?', (analysis_id,)).fetchone()
        if not row:
            return app_error('not found', 404)
        return jsonify(dict(row))

    @app.post('/analyses')
    @require_role('analyst')
    def create_analysis():
        data = request.get_json(force=True)
        db = get_db()
        cur = db.execute('INSERT INTO analyses(project_id, name, description, status) VALUES (?, ?, ?, ?)', (data['project_id'], data['name'], data.get('description', ''), data.get('status', 'draft')))
        db.commit()
        return jsonify({'id': cur.lastrowid}), 201

    @app.get('/analyses/<int:analysis_id>/items')
    def list_items(analysis_id):
        rows = get_db().execute('SELECT * FROM items WHERE analysis_id=? ORDER BY id', (analysis_id,)).fetchall()
        return jsonify([serialize_item(r) for r in rows])

    @app.post('/analyses/<int:analysis_id>/items')
    @require_role('analyst')
    def create_item(analysis_id):
        data = request.get_json(force=True)
        kind = data['kind']
        classifications = data.get('classifications', [])
        if kind == 'requirement' and data.get('source_policy_ref') and not data.get('rationale'):
            return app_error('trace links and rationale required for policy-derived requirements')
        if kind in {'goal', 'requirement'} and not data.get('title'):
            return app_error('title required')
        item = (
            analysis_id, kind, data['title'], data.get('description', ''), data.get('actor'), data.get('trigger'), data.get('outcome'), json.dumps(classifications), data.get('source_policy_ref'), data.get('source_policy_excerpt'), data.get('rationale'), data.get('sensitive_notes'), data.get('legal_compliance'), 1, g.actor['user'], now_iso(), g.actor['user'], now_iso()
        )
        db = get_db()
        cur = db.execute('''INSERT INTO items(analysis_id, kind, title, description, actor, trigger, outcome, classifications, source_policy_ref, source_policy_excerpt, rationale, sensitive_notes, legal_compliance, active, created_by, created_at, updated_by, updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)''', item)
        db.commit()
        audit('item', cur.lastrowid, 'create', None, data)
        return jsonify({'id': cur.lastrowid}), 201

    @app.patch('/items/<int:item_id>')
    @require_role('analyst')
    def update_item(item_id):
        db = get_db()
        row = db.execute('SELECT * FROM items WHERE id=?', (item_id,)).fetchone()
        if not row:
            return app_error('not found', 404)
        data = request.get_json(force=True)
        prev = dict(row)
        new = dict(row)
        for k in ['title','description','actor','trigger','outcome','source_policy_ref','source_policy_excerpt','rationale','sensitive_notes','legal_compliance','active']:
            if k in data:
                new[k] = data[k]
        if 'classifications' in data:
            new['classifications'] = json.dumps(data['classifications'])
        new['updated_by'] = g.actor['user']; new['updated_at'] = now_iso(); new['version'] = row['version'] + 1
        db.execute('''UPDATE items SET title=?, description=?, actor=?, trigger=?, outcome=?, classifications=?, source_policy_ref=?, source_policy_excerpt=?, rationale=?, sensitive_notes=?, legal_compliance=?, active=?, updated_by=?, updated_at=?, version=? WHERE id=?''', (new['title'], new['description'], new['actor'], new['trigger'], new['outcome'], new['classifications'], new['source_policy_ref'], new['source_policy_excerpt'], new['rationale'], new['sensitive_notes'], new['legal_compliance'], new['active'], new['updated_by'], new['updated_at'], new['version'], item_id))
        db.commit()
        audit('item', item_id, 'update', prev, new)
        return jsonify({'status': 'updated'})

    @app.post('/links')
    @require_role('analyst')
    def create_link():
        data = request.get_json(force=True)
        db = get_db()
        cur = db.execute('INSERT INTO links(source_item_id, target_item_id, relation, primary_link, created_by, created_at, note) VALUES (?, ?, ?, ?, ?, ?, ?)', (data['source_item_id'], data['target_item_id'], data['relation'], 1 if data.get('primary_link') else 0, g.actor['user'], now_iso(), data.get('note', '')))
        db.commit()
        audit('link', cur.lastrowid, 'create', None, data)
        return jsonify({'id': cur.lastrowid}), 201

    @app.get('/compare/<int:a>/<int:b>')
    def compare(a, b):
        db = get_db()
        ia = [serialize_item(r) for r in db.execute('SELECT * FROM items WHERE analysis_id=?', (a,)).fetchall()]
        ib = [serialize_item(r) for r in db.execute('SELECT * FROM items WHERE analysis_id=?', (b,)).fetchall()]
        return jsonify({'analysis_a': a, 'analysis_b': b, 'items_a': ia, 'items_b': ib})

    @app.get('/audit')
    def audit_log():
        rows = get_db().execute('SELECT * FROM audits ORDER BY id DESC').fetchall()
        return jsonify([dict(r) for r in rows])

    @app.get('/export/<int:analysis_id>.<fmt>')
    def export_analysis(analysis_id, fmt):
        actor = actor_from_request()
        analysis = get_db().execute('SELECT * FROM analyses WHERE id=?', (analysis_id,)).fetchone()
        if not analysis:
            return app_error('not found', 404)
        project = project_visible(analysis['project_id'])
        if sensitivity_block(actor, project):
            return app_error('forbidden', 403)
        items = [serialize_item(r) for r in get_db().execute('SELECT * FROM items WHERE analysis_id=?', (analysis_id,)).fetchall()]
        rows = []
        for i in items:
            rows.append({'id': i['id'], 'kind': i['kind'], 'title': i['title'], 'description': i['description'], 'version': i['version'], 'updated_at': i['updated_at'], 'source_policy_ref': i['source_policy_ref'], 'rationale': i['rationale']})
        if fmt == 'json':
            return jsonify({'analysis': dict(analysis), 'items': rows})
        if fmt == 'csv':
            output = io.StringIO()
            writer = csv.DictWriter(output, fieldnames=list(rows[0].keys()) if rows else ['id'])
            writer.writeheader()
            writer.writerows(rows)
            return send_file(io.BytesIO(output.getvalue().encode()), mimetype='text/csv', as_attachment=True, download_name=f'analysis-{analysis_id}.csv')
        return app_error('unsupported export format')

    @app.post('/validate/<int:analysis_id>')
    def validate_analysis(analysis_id):
        db = get_db()
        items = [dict(r) for r in db.execute('SELECT * FROM items WHERE analysis_id=?', (analysis_id,)).fetchall()]
        findings = []
        for item in items:
            if item['kind'] == 'requirement' and item['source_policy_ref'] and not item['rationale']:
                findings.append({'item_id': item['id'], 'severity': 'warning', 'message': 'trace link missing rationale'})
        return jsonify({'analysis_id': analysis_id, 'findings': findings})

    return app
EOF

