import json
from app.server import create_app


def test_smoke_index():
    app = create_app()
    client = app.test_client()
    r = client.get('/')
    assert r.status_code == 200
    assert r.get_json()['service'] == 'SPRAT'


def test_create_and_export():
    app = create_app()
    client = app.test_client()
    headers = {'X-Role': 'admin', 'X-User': 'alice'}
    analysis = client.post('/analyses', json={'project_id': 1, 'name': 'A1'}, headers=headers).get_json()['id']
    item = client.post(f'/analyses/{analysis}/items', json={'kind': 'requirement', 'title': 'Req 1', 'source_policy_ref': 'POL-1', 'rationale': 'Needed'}, headers={'X-Role': 'analyst', 'X-User': 'bob'}).get_json()['id']
    assert item > 0
    exp = client.get(f'/export/{analysis}.json', headers={'X-Role': 'manager', 'X-User': 'carol'})
    assert exp.status_code == 200
    payload = exp.get_json()
    assert payload['analysis']['id'] == analysis
    assert payload['items'][0]['title'] == 'Req 1'


def test_guest_blocked_for_sensitive_project():
    app = create_app()
    client = app.test_client()
    client.post('/projects', json={'name': 'S', 'sensitivity': 'sensitive'}, headers={'X-Role': 'admin'})
    client.post('/analyses', json={'project_id': 2, 'name': 'A2'}, headers={'X-Role': 'admin'})
    r = client.get('/export/2.json', headers={'X-Role': 'guest'})
    assert r.status_code == 403
EOF

